import type { BankQuestion } from "@/lib/bank";

/** Advanced Quantitative Ability (Placement) (Placement Aptitude): 138 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"apt-advanced-quant-1","question":"What is the unit digit of 7⁹⁵?","options":["3","1","9","7"],"answer":0,"explanation":"Unit digits of powers of 7 repeat every 4: 7, 9, 3, 1. 95 = 4 × 23 + 3, so the unit digit is the third in the cycle, 3.","difficulty":"easy","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id": "apt-advanced-quant-2", "question": "The binary number (101101)₂ equals which decimal number?", "options": ["53", "45", "90", "43"], "answer": 1, "explanation": "(101101)₂ = 32 + 8 + 4 + 1 = 45. 90 is what you get by reading one extra 0 (shifting left).", "difficulty": "easy", "source": "TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-3","question":"Find the value of log₂ 64 + log₃ 81.","options":["12","24","10","9"],"answer":2,"explanation":"64 = 2⁶ and 81 = 3⁴, so the sum is 6 + 4 = 10.","difficulty":"easy","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-4","question":"Pipe A fills a tank in 12 hours and pipe B fills it in 15 hours. Opened together, how long do they take to fill the empty tank?","options":["7 h 30 min","13 h 30 min","6 h 20 min","6 h 40 min"],"answer":3,"explanation":"Combined rate = 1/12 + 1/15 = 9/60 = 3/20 tank per hour, so time = 20/3 h = 6 h 40 min. 13 h 30 min is the average of the two times, which is not how rates combine.","difficulty":"easy","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-5","question":"What is the angle between the hour hand and the minute hand of a clock at 3:40?","options":["130°","120°","140°","150°"],"answer":0,"explanation":"Angle = |30H − 5.5M| = |90 − 220| = 130°. 120° ignores the hour hand moving 20° in those 40 minutes.","difficulty":"easy","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-6","question":"What is the 25th term of the arithmetic progression 7, 11, 15, …?","options":["99","103","107","100"],"answer":1,"explanation":"Tₙ = a + (n − 1)d = 7 + 24 × 4 = 103. 107 comes from using 25d instead of 24d.","difficulty":"easy","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-7","question":"What is the remainder when 2¹⁰⁰ is divided by 7?","options":["1","4","2","3"],"answer":2,"explanation":"2³ = 8 ≡ 1 (mod 7). 100 = 3 × 33 + 1, so 2¹⁰⁰ ≡ 2¹ = 2.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-8","question":"The HCF of two numbers is 12 and their LCM is 4620. If one of the numbers is 132, what is the other?","options":["440","396","385","420"],"answer":3,"explanation":"Product of the two numbers = HCF × LCM, so the other number = 12 × 4620 / 132 = 420. Check: 132 = 12 × 11 and 420 = 12 × 35 with 11 and 35 co-prime, so the HCF really is 12.","difficulty":"moderate","source":"Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-9","question":"How many zeros are there at the end of 125! (125 factorial)?","options":["31","28","25","30"],"answer":0,"explanation":"Count the factors of 5: ⌊125/5⌋ + ⌊125/25⌋ + ⌊125/125⌋ = 25 + 5 + 1 = 31. Stopping at 25/30 misses the extra 5s in 25, 50, … and 125.","difficulty":"moderate","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-10","question":"The present ages of A and B are in the ratio 5 : 3. Six years from now the ratio will be 7 : 5. What is A's present age?","options":["10 years","15 years","25 years","20 years"],"answer":1,"explanation":"(5x + 6)/(3x + 6) = 7/5 → 25x + 30 = 21x + 42 → x = 3. A = 5 × 3 = 15 years (B = 9; after 6 years 21 : 15 = 7 : 5).","difficulty":"moderate","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-11","question":"A 60-litre mixture contains milk and water in the ratio 3 : 1. How much water must be added to make the ratio 2 : 1?","options":["15 litres","5 litres","7.5 litres","10 litres"],"answer":2,"explanation":"Milk = 45 L, water = 15 L. For 2 : 1 water must be 45/2 = 22.5 L, so add 22.5 − 15 = 7.5 L.","difficulty":"moderate","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-12","question":"A is twice as efficient as B. Working together they finish a job in 14 days. In how many days can A alone finish it?","options":["18 days","28 days","42 days","21 days"],"answer":3,"explanation":"Let B do 1 unit/day and A 2 units/day. Work = 3 × 14 = 42 units. A alone: 42/2 = 21 days (B alone would take 42).","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-13","question":"26 January 2026 is a Monday. What day of the week is 15 August 2026?","options":["Saturday","Thursday","Sunday","Friday"],"answer":0,"explanation":"Days after 26 Jan: 5 (rest of Jan) + 28 + 31 + 30 + 31 + 30 + 31 + 15 = 201. 201 = 7 × 28 + 5, so 5 days after Monday = Saturday.","difficulty":"moderate","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id": "apt-advanced-quant-14", "question": "The sum of an infinite geometric progression is 20 and its first term is 5. What is its third term?", "options": ["15/4", "45/16", "80/9", "5/4"], "answer": 1, "explanation": "S = a/(1 − r) → 20 = 5/(1 − r) → r = 3/4. Third term = 5 × (3/4)² = 45/16.", "difficulty": "moderate", "source": "Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-15","question":"Given log₁₀ 2 = 0.3010, how many digits does 2⁵⁰ have?","options":["17","50","16","15"],"answer":2,"explanation":"log 2⁵⁰ = 50 × 0.3010 = 15.05. Characteristic 15 means 15 + 1 = 16 digits. 15 forgets the +1.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-16","question":"What is the decimal number 255 written in base 8?","options":["777","357","3FF","377"],"answer":3,"explanation":"255 = 3 × 64 + 7 × 8 + 7, so (255)₁₀ = (377)₈. 3FF is a hexadecimal-looking distractor; FF would be 255 in base 16.","difficulty":"easy","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-17","question":"What is the least number that must be added to 3457 so that the sum is divisible by 11?","options":["8","3","2","5"],"answer":0,"explanation":"Alternating digit sum (from the right): 7 − 5 + 4 − 3 = 3, so 3457 ≡ 3 (mod 11). Add 11 − 3 = 8. 3 is the number to subtract, not add.","difficulty":"easy","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id": "apt-advanced-quant-18", "question": "At what time between 4 and 5 o'clock are the hands of a clock together?", "options": ["22 2/11 min past 4", "21 9/11 min past 4", "20 min past 4", "21 3/11 min past 4"], "answer": 1, "explanation": "The minute hand must gain 20 minute-spaces at 11/12 space per minute: 20 × 12/11 = 240/11 = 21 9/11 minutes past 4.", "difficulty": "moderate", "source": "TCS NQT · Capgemini · Cognizant pattern"},
  {"id": "apt-advanced-quant-19", "question": "A pipe fills a tank in 6 hours. Because of a leak at the bottom it takes 8 hours. How long would the leak take to empty the full tank?", "options": ["12 hours", "48 hours", "24 hours", "14 hours"], "answer": 2, "explanation": "Leak rate = 1/6 − 1/8 = 1/24 tank per hour, so it empties the tank in 24 hours. 14 is just 6 + 8.", "difficulty": "moderate", "source": "AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-20","question":"How many integers x satisfy |2x − 3| < 7?","options":["5","7","8","6"],"answer":3,"explanation":"−7 < 2x − 3 < 7 → −4 < 2x < 10 → −2 < x < 5. Integers: −1, 0, 1, 2, 3, 4 → 6. Counting −2 or 5 (the excluded ends) gives 7 or 8.","difficulty":"moderate","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-21","question":"What is the remainder when 3²⁵⁶ is divided by 13?","options":["3","9","1","27"],"answer":0,"explanation":"3³ = 27 ≡ 1 (mod 13). 256 = 3 × 85 + 1, so 3²⁵⁶ ≡ 3¹ = 3.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-22","question":"How many even divisors does 720 have?","options":["30","24","15","20"],"answer":1,"explanation":"720 = 2⁴ × 3² × 5. An even divisor must take at least one 2: 4 × 3 × 2 = 24. 30 is the total number of divisors (5 × 3 × 2), which includes the 6 odd ones.","difficulty":"moderate","source":"Infosys Mathematical Ability pattern"},
  {"id": "apt-advanced-quant-24", "question": "What is the greatest number that divides 1121, 2157 and 3378 leaving the same remainder in each case?", "options": ["111", "11", "74", "37"], "answer": 3, "explanation": "If all three leave the same remainder, the divisor divides every difference: 2157 − 1121 = 1036 = 37 × 28, 3378 − 2157 = 1221 = 37 × 33, 3378 − 1121 = 2257 = 37 × 61. HCF = 37 (remainder 11 each time).", "difficulty": "hard", "source": "Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-25","question":"What is the least number which leaves remainder 5 when divided by 8, 12 or 20, and is exactly divisible by 11?","options":["605","245","485","1325"],"answer":0,"explanation":"The number is 120k + 5 (LCM of 8, 12, 20 is 120). 120 ≡ 10 ≡ −1 (mod 11), so 5 − k ≡ 0 → k = 5: 120 × 5 + 5 = 605 = 11 × 55. 245 and 485 are of the form 120k + 5 but not multiples of 11.","difficulty":"hard","source":"TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-26", "question": "Ten years ago a father was four times as old as his son. Ten years from now he will be twice as old as his son. What is the ratio of their present ages?", "options": ["7 : 3", "5 : 2", "3 : 1", "4 : 1"], "answer": 1, "explanation": "F − 10 = 4(S − 10) and F + 10 = 2(S + 10). So 4S − 30 + 10 = 2S + 20 → S = 20, F = 50. Ratio 50 : 20 = 5 : 2.", "difficulty": "moderate", "source": "AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-27","question":"A vessel holds 80 litres of pure milk. 8 litres are drawn off and replaced with water, and this is done three times in all. How much milk is left?","options":["64.8 litres","57.6 litres","58.32 litres","56 litres"],"answer":2,"explanation":"Each operation keeps (1 − 8/80) = 0.9 of the milk: 80 × 0.9³ = 58.32 L. 56 L assumes 8 L of milk is removed each time; 64.8 L stops after two operations.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-28","question":"Rice at ₹42/kg is mixed with rice at ₹54/kg. Selling the mixture at ₹57.20/kg gives a 10% profit. In what ratio were they mixed?","options":["1 : 3","2 : 3","5 : 1","1 : 5"],"answer":3,"explanation":"Cost price of mixture = 57.20/1.1 = ₹52. Alligation: (54 − 52) : (52 − 42) = 2 : 10 = 1 : 5 (cheaper : dearer). Using 57.20 directly as the mean gives an impossible ratio.","difficulty":"hard","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id": "apt-advanced-quant-29", "question": "A and B together finish a job in 12 days, B and C in 15 days, and C and A in 20 days. How long would C alone take?", "options": ["40 days", "30 days", "60 days", "24 days"], "answer": 2, "explanation": "2(A + B + C) = 1/12 + 1/15 + 1/20 = 1/5 → A + B + C = 1/10. C = 1/10 − 1/12 = 1/60 → 60 days.", "difficulty": "moderate", "source": "TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-30", "question": "Pipe A fills a tank in 12 hours and pipe B in 18 hours. They are opened alternately for one hour each, starting with A. How long does it take to fill the empty tank?", "options": ["14 1/3 hours", "14.5 hours", "14.4 hours", "15 hours"], "answer": 0, "explanation": "One 2-hour cycle fills 1/12 + 1/18 = 5/36. Six cycles (12 h) fill 30/36. Hour 13 (A) adds 3/36 → 33/36; hour 14 (B) adds 2/36 → 35/36; the last 1/36 is filled by A in (1/36)/(1/12) = 1/3 h. Total 14 1/3 h. 14.5 h lets B run for 1.5 h at the end, but B only gets one hour before A's turn comes back; 14.4 h treats the job as continuous at the average rate.", "difficulty": "hard", "source": "TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-31", "question": "A clock gains 5 minutes every hour. It is set right at 8:00 a.m. What is the correct time when this clock shows 8:00 p.m. the same day?", "options": ["7:04 8/13 p.m.", "7:00 p.m.", "7:05 p.m.", "7:08 4/13 p.m."], "answer": 0, "explanation": "The clock shows 65 min for every 60 real min. 12 h shown = 720 × 60/65 = 664 8/13 real minutes = 11 h 4 8/13 min after 8 a.m., i.e. 7:04 8/13 p.m. 7:00 p.m. wrongly subtracts 60 min (5 × 12).", "difficulty": "hard", "source": "TCS NQT · Capgemini · Cognizant pattern"},
  {"id": "apt-advanced-quant-33", "question": "The calendar of 2026 will be repeated next in which year?", "options": ["2032", "2043", "2037", "2034"], "answer": 2, "explanation": "A year repeats when the odd days in between add to a multiple of 7 and both are ordinary years. From 2026: odd days 1 (2026), 1, 2 (2028), 1, 1, 1, 2 (2032), 1, 1, 1, 2 (2036) = 14 ≡ 0 by the end of 2036, so 2037 starts on Thursday like 2026 and is also non-leap. 2032 is a leap year.", "difficulty": "moderate", "source": "TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-34","question":"What is the sum of all three-digit numbers divisible by 7?","options":["70429","69356","70273","70336"],"answer":3,"explanation":"First = 105, last = 994, count = (994 − 105)/7 + 1 = 128. Sum = 128 × (105 + 994)/2 = 64 × 1099 = 70336.","difficulty":"moderate","source":"Infosys Mathematical Ability pattern"},
  {"id": "apt-advanced-quant-35", "question": "The 4th term of a geometric progression is 24 and the 7th term is 192. What is the sum of its first 6 terms?", "options": ["189", "93", "381", "126"], "answer": 0, "explanation": "ar⁶/ar³ = r³ = 8 → r = 2; a = 24/8 = 3. S₆ = 3(2⁶ − 1)/(2 − 1) = 3 × 63 = 189. 93 is S₅, 381 is S₇.", "difficulty": "moderate", "source": "Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-36","question":"Given log₁₀ 2 = 0.3010 and log₁₀ 3 = 0.4771, find log₁₀ 0.0072.","options":["−2.8572","−2.1428","−3.1428","−1.1428"],"answer":1,"explanation":"0.0072 = 72 × 10⁻⁴ = 2³ × 3² × 10⁻⁴. log = 0.9030 + 0.9542 − 4 = 1.8572 − 4 = −2.1428. −2.8572 wrongly writes the mantissa as negative (the bar form is 3̄.8572).","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-37", "question": "If log₂ x + log₄ x + log₁₆ x = 7, what is x?", "options": ["4", "8", "16", "256"], "answer": 2, "explanation": "Write all in base 2: log₂x (1 + 1/2 + 1/4) = 7 → (7/4) log₂x = 7 → log₂x = 4 → x = 16.", "difficulty": "moderate", "source": "AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-38","question":"How many integers x with −5 ≤ x ≤ 10 satisfy (x − 1)(x − 4)(x − 6) < 0?","options":["6","9","10","7"],"answer":3,"explanation":"Critical points 1, 4, 6. The product is negative for x < 1 and for 4 < x < 6. Integers: −5 to 0 (6 values) and 5 (1 value) = 7. Including the roots (≤ 0) would give 10.","difficulty":"moderate","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-39","question":"Convert (1234)₅ to base 7.","options":["365","1234","356","194"],"answer":0,"explanation":"(1234)₅ = 125 + 50 + 15 + 4 = 194. 194 = 3 × 49 + 6 × 7 + 5, so it is (365)₇. 194 is the decimal value, not base 7.","difficulty":"moderate","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-40","question":"What is the remainder when 5²⁰²⁶ is divided by 11?","options":["4","5","3","1"],"answer":1,"explanation":"5² = 25 ≡ 3, 5⁴ ≡ 9, 5⁵ ≡ 45 ≡ 1 (mod 11). 2026 = 5 × 405 + 1, so 5²⁰²⁶ ≡ 5. Using Fermat's 5¹⁰ ≡ 1 gives the same: 2026 ≡ 6 (mod 10), 5⁶ ≡ 5.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-41","question":"Six children were born at intervals of 2 years. The sum of their present ages is 72 years. What is the age of the eldest child?","options":["15 years","19 years","17 years","12 years"],"answer":2,"explanation":"Youngest y: y + (y + 2) + … + (y + 10) = 6y + 30 = 72 → y = 7. Eldest = 7 + 10 = 17. 19 adds 2 × 6 instead of 2 × 5.","difficulty":"moderate","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-42","question":"12 men or 18 women can finish a job in 14 days. In how many days will 8 men and 16 women finish it?","options":["10 days","8 days","12 days","9 days"],"answer":3,"explanation":"12 men = 18 women, so 1 man = 1.5 women and 8 men = 12 women. Team = 28 women. Days = 18 × 14 / 28 = 9.","difficulty":"moderate","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-43","question":"What is the remainder when 1! + 2! + 3! + … + 100! is divided by 24?","options":["9","33","15","0"],"answer":0,"explanation":"From 4! = 24 onwards every factorial is a multiple of 24. So the remainder is that of 1 + 2 + 6 = 9. 33 includes 4! (which is 0 mod 24) and is itself larger than 24.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-44", "question": "What are the last two digits of 2²⁰²⁶?", "options": ["76", "64", "04", "24"], "answer": 1, "explanation": "Mod 4 the number is 0. Mod 25: 2¹⁰ = 1024 ≡ −1, so 2²⁰ ≡ 1 and 2²⁰²⁶ ≡ 2⁶ = 64 ≡ 14 (mod 25). The number ≡ 0 (mod 4) and ≡ 14 (mod 25) is 64. 76 is 2²⁰ᵏ (mod 100), which applies only when the exponent is a multiple of 20.", "difficulty": "hard", "source": "TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-45", "question": "What are the last two digits of 7²⁰²⁶?", "options": ["07", "01", "49", "43"], "answer": 2, "explanation": "7⁴ = 2401 ≡ 01 (mod 100). 2026 = 4 × 506 + 2, so 7²⁰²⁶ ≡ 7² = 49.", "difficulty": "hard", "source": "Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-46","question":"What is the unit digit of 2^(3^4), that is, 2 raised to the power 3⁴?","options":["4","8","6","2"],"answer":3,"explanation":"A tower is evaluated from the top: 3⁴ = 81, so the number is 2⁸¹. 81 ≡ 1 (mod 4) → unit digit 2. Reading it as (2³)⁴ = 2¹² gives 6, the common trap.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-47", "question": "How many zeros are there at the end of 50! when it is written in base 12?", "options": ["22", "12", "23", "47"], "answer": 0, "explanation": "12 = 2² × 3. Power of 2 in 50! = 25 + 12 + 6 + 3 + 1 = 47 → 47 // 2 = 23 copies of 2². Power of 3 = 16 + 5 + 1 = 22. Zeros = min(23, 22) = 22. 23 forgets that 3 is the scarcer factor here.", "difficulty": "hard", "source": "TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-48","question":"In how many ways can 1440 be written as a product of two natural numbers (order not counted, so 2 × 720 and 720 × 2 are the same)?","options":["17","18","19","36"],"answer":1,"explanation":"1440 = 2⁵ × 3² × 5, so it has 6 × 3 × 2 = 36 divisors. It is not a perfect square, so they pair up into 36/2 = 18 products. 36 counts ordered pairs.","difficulty":"hard","source":"Infosys Mathematical Ability pattern"},
  {"id": "apt-advanced-quant-49", "question": "The sum of two numbers is 528 and their HCF is 33. How many such pairs of numbers exist?", "options": ["5", "8", "4", "3"], "answer": 2, "explanation": "Write the numbers as 33a and 33b with a, b co-prime: a + b = 16. Co-prime pairs with a < b: (1, 15), (3, 13), (5, 11), (7, 9) → 4 pairs. (2, 14), (4, 12), (6, 10) and (8, 8) are excluded because they share a factor, which would make the HCF larger than 33.", "difficulty": "hard", "source": "Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-50","question":"Four bells toll together at 9:00 a.m. and then toll at intervals of 12, 15, 20 and 27 seconds respectively. How many times do they toll together from 9:00 a.m. up to and including 10:00 a.m.?","options":["8","6","5","7"],"answer":3,"explanation":"LCM(12, 15, 20, 27) = 540 s = 9 min. In 60 min they coincide at 9, 18, …, 54 min (6 times) after the start; adding the toll at 9:00 a.m. gives 7. 10:00 a.m. (60 min) is not a multiple of 9 min.","difficulty":"hard","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-51","question":"In base b, (45)_b + (36)_b = (103)_b. What is b?","options":["8","6","7","9"],"answer":0,"explanation":"(4b + 5) + (3b + 6) = b² + 3 → b² − 7b − 8 = 0 → (b − 8)(b + 1) = 0 → b = 8. Every digit (≤ 6) is valid in base 8. Base 7 fails because the left side would be 64, and (103)₇ = 52.","difficulty":"moderate","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-52","question":"The number (777)₈ + 1 is written in base 4. What is the result?","options":["100000","20000","10000","13333"],"answer":1,"explanation":"(777)₈ = 511, so (777)₈ + 1 = 512 = 2 × 256 = 2 × 4⁴, i.e. (20000)₄. 10000₄ = 256 and 100000₄ = 1024. 13333₄ is 511 itself.","difficulty":"moderate","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-53","question":"Ravi is now twice as old as Sita was when Ravi was as old as Sita is now. The sum of their present ages is 63 years. How old is Ravi now?","options":["42 years","35 years","36 years","27 years"],"answer":2,"explanation":"Let Ravi = R, Sita = S (R > S). Ravi was S years old R − S years ago; Sita was then S − (R − S) = 2S − R. So R = 2(2S − R) → 3R = 4S. With R + S = 63: S = 27, R = 36. 27 is Sita's age.","difficulty":"hard","source":"Infosys Mathematical Ability pattern"},
  {"id": "apt-advanced-quant-54", "question": "Vessel A has milk and water in the ratio 5 : 3, and vessel B has them in the ratio 2 : 3. In what ratio must the contents of A and B be mixed to get a mixture with equal milk and water?", "options": ["3 : 2", "8 : 5", "5 : 4", "4 : 5"], "answer": 3, "explanation": "Milk fractions: A = 5/8, B = 2/5, target 1/2. Alligation: (1/2 − 2/5) : (5/8 − 1/2) = 1/10 : 1/8 = 4 : 5. Reversing the differences gives 5 : 4.", "difficulty": "hard", "source": "AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-55","question":"From a 40-litre can of pure milk, a certain quantity is taken out and replaced with water. The process is repeated once more with the same quantity. The can now has 22.5 litres of milk. How much was taken out each time?","options":["10 litres","8.75 litres","12 litres","8 litres"],"answer":0,"explanation":"40 (1 − x/40)² = 22.5 → (1 − x/40)² = 9/16 → 1 − x/40 = 3/4 → x = 10 L. 8.75 L comes from assuming a linear loss of 17.5 L split over two steps.","difficulty":"hard","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-56","question":"Three alloys have copper and zinc in the ratios 1 : 2, 2 : 3 and 3 : 4. Equal weights of the three are melted together. What is the ratio of copper to zinc in the new alloy?","options":["2 : 3","122 : 193","1 : 2","6 : 9"],"answer":1,"explanation":"Copper fractions 1/3, 2/5, 3/7. Mean copper = (35 + 42 + 45)/105 ÷ 3 = 122/315, so zinc = 193/315 → 122 : 193. Adding the ratio terms (1+2+3 : 2+3+4 = 6 : 9) is wrong because the alloys are mixed by equal weight, not by those parts.","difficulty":"moderate","source":"Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-57","question":"Pipes A, B and C can fill a tank in 6, 8 and 12 hours respectively. A is opened at 12 noon, B at 1 p.m. and C at 2 p.m. At what time is the tank full?","options":["3:20 p.m.","2:40 p.m.","3:26 2/3 p.m.","3:44 4/9 p.m."],"answer":2,"explanation":"With t hours after noon: t/6 + (t − 1)/8 + (t − 2)/12 = 1 → 4t + 3t − 3 + 2t − 4 = 24 → t = 31/9 h = 3 h 26 2/3 min. 3:44 4/9 p.m. misreads 3 4/9 h as 3 h 44 4/9 min (the fraction is of an hour: 4/9 × 60 = 26 2/3 min).","difficulty":"hard","source":"TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-58", "question": "A cistern has two inlet pipes that fill it in 20 minutes and 30 minutes, and one outlet pipe. With all three open, the empty cistern fills in 18 minutes. How long would the outlet alone take to empty the full cistern?", "options": ["45 minutes", "60 minutes", "12 minutes", "36 minutes"], "answer": 3, "explanation": "1/20 + 1/30 − 1/x = 1/18 → 1/12 − 1/18 = 1/x → 1/x = 1/36 → 36 minutes. 12 minutes is the time of the two inlets together.", "difficulty": "hard", "source": "AMCAT · Wipro NLTH · Accenture pattern"},
  {"id": "apt-advanced-quant-59", "question": "When, for the first time after 5 o'clock, are the hands of a clock at right angles?", "options": ["10 10/11 min past 5", "15 min past 5", "10 min past 5", "43 7/11 min past 5"], "answer": 0, "explanation": "At 5:00 the angle is 150°. It falls to 90° when 150 − 5.5m = 90 → m = 60/5.5 = 10 10/11 min. 43 7/11 min past 5 is the second right angle (5.5m − 150 = 90).", "difficulty": "moderate", "source": "TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-60","question":"At what time between 2 and 3 o'clock are the hands of a clock pointing in exactly opposite directions?","options":["10 10/11 min past 2","43 7/11 min past 2","42 6/11 min past 2","40 min past 2"],"answer":1,"explanation":"At 2:00 the minute hand is 60° behind the hour hand. It must get 180° ahead: 5.5m = 60 + 180 = 240 → m = 43 7/11 min. 10 10/11 min past 2 is when the hands coincide.","difficulty":"moderate","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id": "apt-advanced-quant-61", "question": "One watch loses 10 minutes a day and another gains 8 minutes a day. Both are set to the correct time together. After how many days will they next show the same time?", "options": ["72 days", "80 days", "40 days", "36 days"], "answer": 2, "explanation": "They drift apart by 10 + 8 = 18 min a day. Dials repeat every 12 hours = 720 min, so they agree again after 720/18 = 40 days. 80 days uses 24 hours (1440 min), but a 12-hour dial shows the same time after a 12-hour gap.", "difficulty": "hard", "source": "TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-62","question":"Today is Saturday. What day of the week will it be after 3¹⁰⁰ days?","options":["Sunday","Tuesday","Friday","Wednesday"],"answer":3,"explanation":"3⁶ ≡ 1 (mod 7). 100 = 6 × 16 + 4, so 3¹⁰⁰ ≡ 3⁴ = 81 ≡ 4 (mod 7). Saturday + 4 days = Wednesday.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-63","question":"1 January 2001 was a Monday. What day of the week was 1 January 2101?","options":["Saturday","Monday","Friday","Sunday"],"answer":0,"explanation":"From 2001 to 2100 there are 100 years with 24 leap years (2004, …, 2096; 2100 is not a leap year). Odd days = 100 + 24 = 124 ≡ 5 (mod 7). Monday + 5 = Saturday. Counting 2100 as leap gives Sunday.","difficulty":"hard","source":"TCS NQT · Capgemini · Cognizant pattern"},
  {"id":"apt-advanced-quant-64","question":"The sum of the first n terms of an arithmetic progression is 3n² + 5n. What is its 15th term?","options":["87","92","95","750"],"answer":1,"explanation":"T₁₅ = S₁₅ − S₁₄ = (675 + 75) − (588 + 70) = 750 − 658 = 92. (Generally Tₙ = 6n + 2.) 750 is S₁₅ itself.","difficulty":"moderate","source":"Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-65","question":"How many terms are common to the two progressions 3, 7, 11, …, 407 and 2, 9, 16, …, 709?","options":["25","15","14","13"],"answer":2,"explanation":"Common terms satisfy x ≡ 3 (mod 4) and x ≡ 2 (mod 7); the first is 23, and they repeat every LCM(4, 7) = 28. Need 23 + 28k ≤ 407 → k ≤ 13.7 → k = 0 to 13 → 14 terms. Using the larger last term 709 gives 25.","difficulty":"hard","source":"Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-66","question":"Three numbers in geometric progression have product 216 and the sum of their products taken two at a time is 156. What is the largest of the three numbers?","options":["24","54","12","18"],"answer":3,"explanation":"Take a/r, a, ar. a³ = 216 → a = 6. Pairwise sum = 36(1/r + 1 + r) = 156 → r + 1/r = 10/3 → r = 3 (or 1/3). The numbers are 2, 6, 18, so the largest is 18.","difficulty":"hard","source":"Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-67","question":"Find the sum to infinity: 1 + 2/3 + 3/9 + 4/27 + 5/81 + …","options":["9/4","27/8","3/2","3"],"answer":0,"explanation":"This is an arithmetico-geometric series Σ n xⁿ⁻¹ with x = 1/3, whose sum is 1/(1 − x)² = 1/(2/3)² = 9/4. 3/2 is the sum of the plain GP 1 + 1/3 + 1/9 + ….","difficulty":"hard","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-68","question":"If log_a b = 2 and log_b c = 3, what is the value of log_(ab) c?","options":["1/2","2","3/2","6"],"answer":1,"explanation":"b = a², c = b³ = a⁶. log_(ab) c = log a⁶ / log a³ = 6/3 = 2. 6 is log_a c, which forgets the base is ab.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-69","question":"Given log₁₀ 2 = 0.3010, how many zeros are there between the decimal point and the first significant digit of (1/2)³⁰?","options":["8","30","9","10"],"answer":2,"explanation":"log (1/2)³⁰ = −30 × 0.3010 = −9.03 = 10̄.97 (characteristic −10). A characteristic of −n means n − 1 zeros after the point: 9 zeros. Indeed 2⁻³⁰ ≈ 0.000000000931.","difficulty":"hard","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-70","question":"a and b are positive real numbers with a + b = 10. What is the maximum value of ab²?","options":["1000/9","250/3","125","4000/27"],"answer":3,"explanation":"Split b into two halves: a + b/2 + b/2 = 10. By AM ≥ GM, a(b/2)(b/2) ≤ (10/3)³, so ab² ≤ 4 × 1000/27 = 4000/27 ≈ 148.1, at a = 10/3, b = 20/3. 125 comes from a = b = 5, which maximises ab, not ab².","difficulty":"hard","source":"TCS NQT Advanced · Infosys pattern"},
  {"id":"apt-advanced-quant-71","question":"How many integers x in the range −3 ≤ x ≤ 6 satisfy (x² − 5x + 4)/(x − 3) ≤ 0?","options":["6","5","4","7"],"answer":0,"explanation":"(x − 1)(x − 4)/(x − 3) ≤ 0 holds for x ≤ 1 and for 3 < x ≤ 4 (x = 3 is excluded, the expression is undefined). Integers: −3, −2, −1, 0, 1 and 4 → 6. Counting x = 3 gives 7.","difficulty":"hard","source":"AMCAT · Wipro NLTH · Accenture pattern"},
  {"id": "apt-advanced-quant-72", "question": "The number 123456789101112…4950 is formed by writing the integers 1 to 50 one after another. What is the remainder when it is divided by 9?", "options": ["5", "6", "3", "0"], "answer": 1, "explanation": "A number ≡ its digit sum (mod 9), and the digit sum of each block k ≡ k (mod 9). So the number ≡ 1 + 2 + … + 50 = 1275 ≡ 1 + 2 + 7 + 5 = 15 ≡ 6 (mod 9).", "difficulty": "moderate", "source": "TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-73", "question": "a and b are digits such that the five-digit number 7a5b2 is divisible by 72. How many such numbers are there?", "options": ["4", "3", "1", "2"], "answer": 1, "explanation": "72 = 8 × 9. Divisible by 8: 5b2 must be a multiple of 8 → b = 1, 5 or 9 (512, 552, 592). Divisible by 9: 14 + a + b ≡ 0 (mod 9) → a + b = 4 or 13 → (a, b) = (3, 1), (8, 5), (4, 9). Numbers 73512, 78552, 74592 → 3.", "difficulty": "hard", "source": "Infosys Mathematical Ability pattern"},
  {"id":"apt-advanced-quant-74","question":"What is the HCF of 2¹² − 1 and 2¹⁸ − 1?","options":["4095","3","63","7"],"answer":2,"explanation":"gcd(2ᵐ − 1, 2ⁿ − 1) = 2^gcd(m, n) − 1. gcd(12, 18) = 6, so the HCF is 2⁶ − 1 = 63. 7 = 2³ − 1 is a common factor, but not the highest.","difficulty":"moderate","source":"TCS NQT Advanced · Infosys pattern"},
  {"id": "apt-advanced-quant-75", "question": "A and B undertake a job for ₹5400. A alone can do it in 9 days and B alone in 12 days. With the help of C they finish it in 4 days. What is C's share of the payment if it is in proportion to work done?", "options": ["₹1800", "₹1350", "₹600", "₹1200"], "answer": 3, "explanation": "C's rate = 1/4 − 1/9 − 1/12 = (9 − 4 − 3)/36 = 1/18. In 4 days C does 4/18 = 2/9 of the job, so C gets 2/9 × 5400 = ₹1200. ₹1800 is an equal three-way split, but shares follow the work done.", "difficulty": "hard", "source": "AMCAT · Wipro NLTH · Accenture pattern"},
  {"id":"apt-advanced-quant-76","question":"The mirror image of a wall clock (reflected left to right) shows 4:35. What is the actual time on the clock?","options":["7:25","8:25","7:35","4:25"],"answer":0,"explanation":"For a left–right mirror, actual time = 11:60 − mirror time = 11:60 − 4:35 = 7:25. 8:25 comes from subtracting from 12:60 instead of 11:60; 7:35 forgets to flip the minutes.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-77","question":"What is the smaller angle between the hour and minute hands of a clock at 7:20?","options":["110°","100°","90°","80°"],"answer":1,"explanation":"Angle = |30H − 5.5M| = |210 − 110| = 100°. 110° is the minute hand alone (5.5 × 20); 80° ignores that the hour hand has moved 10° past the 7.","difficulty":"easy","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-78","question":"A laptop is sold after two successive discounts of 20% and 10% on its list price. What single discount is equivalent to these two?","options":["30%","27%","28%","29%"],"answer":2,"explanation":"Price paid = 0.8 × 0.9 = 0.72 of list, so the single discount is 28%. Adding the two (30%) forgets that the second discount applies to an already reduced price.","difficulty":"easy","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-79","question":"1 March of a certain year is a Monday. What day of the week is 1 April of the same year?","options":["Wednesday","Friday","Monday","Thursday"],"answer":3,"explanation":"March has 31 days = 4 weeks + 3 odd days, so 1 April is 3 days after Monday: Thursday. Wednesday comes from treating March as 30 days.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-80","question":"A wall clock is set right at 6:00 a.m. on Monday. It loses 12 minutes every 24 hours, at a uniform rate. What time does it show at the true time of 6:00 p.m. on Wednesday?","options":["5:30 p.m.","5:36 p.m.","5:24 p.m.","6:30 p.m."],"answer":0,"explanation":"From 6 a.m. Monday to 6 p.m. Wednesday is 2.5 days, so the clock loses 2.5 × 12 = 30 minutes and shows 5:30 p.m. 5:36 p.m. counts only 2 days; 6:30 p.m. adds the loss instead of subtracting it.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-81","question":"A can finish a project in 20 days and B in 30 days. They start together, but A leaves 5 days before the project is completed. In how many days is the project completed?","options":["12 days","15 days","17 days","14 days"],"answer":1,"explanation":"If the project takes t days, A works t − 5 days and B works t days: (t − 5)/20 + t/30 = 1 ⇒ 3t − 15 + 2t = 60 ⇒ t = 15. 12 days is the time if both worked throughout; 17 days adds the 5 days to the wrong base.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-82","question":"Pipes A and B fill a tank in 12 hours and 15 hours respectively, while pipe C empties it in 20 hours. All three are opened together at 9:00 a.m. on an empty tank. At what time is the tank full?","options":["3:40 p.m.","6:00 p.m.","7:00 p.m.","8:00 p.m."],"answer":2,"explanation":"Net rate = 1/12 + 1/15 − 1/20 = (5 + 4 − 3)/60 = 1/10 tank per hour, so it takes 10 hours: 9 a.m. + 10 h = 7 p.m. 3:40 p.m. ignores pipe C (6 h 40 min).","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-83","question":"1 January 2028 is a Saturday, and 2028 is a leap year. How many Sundays are there in 2028?","options":["52","54","51","53"],"answer":3,"explanation":"A leap year has 52 weeks + 2 odd days. Those two extra days are the first two days of the year, Saturday and Sunday, so both Saturday and Sunday occur 53 times. 52 forgets the odd days.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-84","question":"What is the remainder when 2²⁰²⁶ + 3²⁰²⁶ is divided by 5?","options":["3","0","4","1"],"answer":0,"explanation":"Powers of 2 and 3 repeat their last digit every 4. 2026 = 4 × 506 + 2, so 2²⁰²⁶ ends in 4 and 3²⁰²⁶ ends in 9; the sum ends in 3, so the remainder is 3. 0 is a guess from 2 + 3 = 5; 4 takes only one of the two terms.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-85","question":"The present ages of A and B are in the ratio 4 : 5. A’s age 8 years ago was equal to B’s age 14 years ago. What is B’s present age?","options":["24 years","30 years","35 years","28 years"],"answer":1,"explanation":"A − 8 = B − 14 ⇒ B − A = 6. With A = 4x and B = 5x, x = 6, so B = 30 (A = 24). 24 is A’s age, not B’s.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-86","question":"A clock strikes once at 1 o’clock, twice at 2 o’clock, and so on up to 12 times at 12 o’clock. It also strikes once at every half-hour. How many times does it strike in one full day (24 hours)?","options":["156","168","180","102"],"answer":2,"explanation":"In 12 hours: 1 + 2 + … + 12 = 78 hourly strikes plus 12 half-hour strikes = 90. In 24 hours, 180. 156 forgets the half-hour strikes; 102 counts only one 12-hour cycle of hours plus all 24 half-hours.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-87","question":"Pipes A and B can fill a tank in 10 hours and 15 hours. When both are opened together, the tank takes 7 hours 30 minutes to fill because of a leak at the bottom. How long would the leak alone take to empty the full tank?","options":["24 hours","40 hours","25 hours","30 hours"],"answer":3,"explanation":"Without the leak, A + B fill at 1/10 + 1/15 = 1/6 per hour. With the leak the rate is 1/7.5 = 2/15. Leak rate = 1/6 − 2/15 = 1/30, so 30 hours. 25 hours wrongly subtracts the times (7.5 vs 6 h) as if times added like rates.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-88","question":"Pipe A fills a tank in 4 hours and pipe B in 6 hours. A leak, open all the time, can empty the full tank in 12 hours. A and B are opened alternately for one hour each, starting with A, while the leak keeps working. How long does it take to fill the empty tank?","options":["8 hours","4 hours 40 minutes","7 hours 30 minutes","9 hours"],"answer":0,"explanation":"Net per hour: A-hour 1/4 − 1/12 = 1/6, B-hour 1/6 − 1/12 = 1/12, so each 2-hour pair adds 1/4. After 6 hours the tank is 3/4 full. Hour 7 (A) adds 1/6 → 11/12; hour 8 (B) adds exactly 1/12 → full at 8 hours. 4 h 40 min is the answer without the leak; 7 h 30 min wrongly assumes the tank fills during A’s 7th hour.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-89","question":"1 January 2000 was a Saturday. What day of the week is 1 January 2100?","options":["Thursday","Friday","Saturday","Sunday"],"answer":1,"explanation":"From 1 Jan 2000 to 1 Jan 2100 covers the years 2000–2099: 100 years with 25 leap years (2000 is a leap year, being divisible by 400). Odd days = 100 + 25 = 125 ≡ 6 (mod 7), and Saturday + 6 = Friday. Thursday comes from forgetting that 2000 is a leap year (24 leap years).","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-90","question":"A is 50% more efficient than B. C does, in one day, half the work that A and B together do in one day. If C alone can finish a job in 30 days, how many days will A alone take?","options":["20 days","37.5 days","25 days","15 days"],"answer":2,"explanation":"Let A’s rate be a; then B = a/1.5 = 2a/3 and C = (a + 2a/3)/2 = 5a/6. C = 1/30 ⇒ a = 6/150 = 1/25, so A takes 25 days. 37.5 days is B’s time; 15 days is A and B together.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-91","question":"A man travels a fixed distance by scooter. Had he driven 3 km/h faster, he would have taken 40 minutes less; had he driven 2 km/h slower, he would have taken 40 minutes more. What is the distance?","options":["36 km","48 km","30 km","40 km"],"answer":3,"explanation":"d/v − d/(v + 3) = 2/3 and d/(v − 2) − d/v = 2/3 give 3d/(v(v + 3)) = 2d/(v(v − 2)), so 3(v − 2) = 2(v + 3) and v = 12 km/h. Then d · 3/(12 × 15) = 2/3 ⇒ d = 40 km. Check: 40/12 − 40/15 = 2/3 h and 40/10 − 40/12 = 2/3 h.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-92","question":"A starts a business with ₹40,000. B joins after 3 months with ₹60,000. At the end of the 6th month, A withdraws half of his capital. Out of a year-end profit of ₹33,000, what is B’s share?","options":["₹19,800","₹13,200","₹16,500","₹18,000"],"answer":0,"explanation":"Capital × months: A = 40,000 × 6 + 20,000 × 6 = 3,60,000; B = 60,000 × 9 = 5,40,000. Ratio 2 : 3, so B gets 3/5 × 33,000 = ₹19,800. ₹13,200 is A’s share; ₹16,500 ignores time and withdrawal.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-93","question":"What is the largest power of 6 that divides 40! (40 factorial)?","options":["6⁶","6¹⁸","6³⁸","6¹³"],"answer":1,"explanation":"Powers of 2 in 40! = 20 + 10 + 5 + 2 + 1 = 38; powers of 3 = 13 + 4 + 1 = 18. Each 6 needs one 2 and one 3, so the 3s run out first: 6¹⁸. 6⁶ is just ⌊40/6⌋, which ignores that 2s and 3s come from different numbers; 6¹³ stops at ⌊40/3⌋.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-94","question":"In an election between two candidates, 10% of the voters on the list did not vote and 60 votes cast were invalid. The winner got 47% of all the voters on the list and won by 308 votes. How many voters were on the list?","options":["7700","5800","6200","6600"],"answer":2,"explanation":"Let N be the list size. Valid votes = 0.9N − 60; winner = 0.47N; loser = 0.9N − 60 − 0.47N = 0.43N − 60. Margin = 0.04N + 60 = 308 ⇒ N = 6200 (winner 2914, loser 2606). 7700 forgets the invalid votes (0.04N = 308).","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-95","question":"Pipes A and B fill a tank in 20 minutes and 30 minutes respectively. Both are opened on an empty tank, but after some time B is closed, and the tank is full exactly 15 minutes after the start. After how many minutes was B closed?","options":["5 minutes","10 minutes","12 minutes","7.5 minutes"],"answer":3,"explanation":"A works all 15 minutes and fills 15/20 = 3/4. B must fill the other 1/4, which takes 30/4 = 7.5 minutes. 12 minutes is the time both together need to fill the tank, which has nothing to do with B’s share.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-96","question":"A pipe can fill a tank in 12 hours. When the tank is exactly half full, a leak develops at the bottom, and the tank ends up taking 14 hours in total to fill. How long would the leak alone take to empty the full tank?","options":["48 hours","84 hours","24 hours","42 hours"],"answer":0,"explanation":"The first half takes 6 hours as usual, so the second half takes 8 hours: net rate 1/2 ÷ 8 = 1/16. Leak = 1/12 − 1/16 = 1/48, so 48 hours. 84 hours wrongly treats the leak as working for the whole 14 hours (1/12 − 1/14).","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-97","question":"In a 1 km race, A beats B by 40 m and B beats C by 50 m. Running at the same speeds, by how many metres does A beat C in a 1 km race?","options":["90 m","88 m","10 m","92 m"],"answer":1,"explanation":"When A runs 1000 m, B runs 960 m. C runs 950 m for every 1000 m of B, so in that time C runs 960 × 0.95 = 912 m. A wins by 88 m. 90 m adds the margins, ignoring that B’s 50 m lead is over a full 1000 m.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-98","question":"A train overtakes a man walking at 3.6 km/h in 10 seconds and a cyclist riding at 7.2 km/h in 11 seconds, both moving in the same direction as the train. What is the length of the train?","options":["120 m","100 m","110 m","132 m"],"answer":2,"explanation":"In m/s the man moves at 1 and the cyclist at 2. With train speed u, L = 10(u − 1) = 11(u − 2) ⇒ u = 12 m/s (43.2 km/h) and L = 110 m. 120 m uses the train’s full speed for 10 s, forgetting the relative speed.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-99","question":"Counting both 9:00 a.m. and 9:00 p.m. themselves, how many times between 9:00 a.m. and 9:00 p.m. on the same day are the hands of a clock exactly at right angles?","options":["22","24","44","23"],"answer":3,"explanation":"The hands are at right angles 22 times in every 12 hours, i.e. every 360/11 minutes. At 9:00 the hands are already at 90°, so the moments are t = 0, 360/11, …, 22 × 360/11 = 720 minutes: k = 0 to 22 gives 23 instants, because both ends are included. 22 is the half-open count; 44 is for a whole day.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-100","question":"The minute and hour hands of a faulty clock coincide every 64 minutes of true time. How much does the clock gain or lose in a day (24 hours of true time)?","options":["Gains 32 8/11 minutes","Loses 32 8/11 minutes","Gains 1 5/11 minutes","Loses 10 10/43 minutes"],"answer":0,"explanation":"On a correct clock the hands coincide every 720/11 = 65 5/11 minutes of clock time. Here that much clock time passes in only 64 true minutes, so the clock runs fast, gaining 16/11 minutes per 64 minutes. Per day: 1440/64 × 16/11 = 360/11 = 32 8/11 minutes gained. \"Loses\" mixes up the direction; 1 5/11 is the gain per coincidence only.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-101","question":"In a certain leap year, 29 February falls on a Thursday. Assuming no century year intervenes, on which day does 29 February fall in the next leap year?","options":["Monday","Tuesday","Wednesday","Friday"],"answer":1,"explanation":"From one 29 February to the next is 4 years = 365 × 3 + 366 = 1461 days, and 1461 ≡ 5 (mod 7). Thursday + 5 = Tuesday. Monday counts 4 odd days (four ordinary years); Friday is one day per year.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-102","question":"A 300-digit number is formed by writing the block 123 one hundred times: 123123123…123. What is the remainder when it is divided by 99?","options":["6","0","33","24"],"answer":2,"explanation":"Work modulo 9 and 11. Digit sum = 100 × 6 = 600 ≡ 6 (mod 9). For 11, since 1000 ≡ −1 (mod 11), the number ≡ 123 × (1 − 1 + 1 − … − 1) = 0 (mod 11), because there are 100 blocks. The remainder r < 99 with r ≡ 0 (mod 11) and r ≡ 6 (mod 9) is 33. 6 is only the remainder mod 9.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-103","question":"12 men can finish a job in 18 days. They start together; after 6 days, 4 men leave, and 6 days after that, 8 women join the remaining men. A woman does half the work of a man per day. How many more days are needed to finish the job after the women join?","options":["6 days","12 days","10 days","8 days"],"answer":3,"explanation":"Total work = 12 × 18 = 216 man-days. Done: 12 × 6 = 72, then 8 × 6 = 48, leaving 96. 8 men + 8 women = 8 + 4 = 12 man-equivalents, so 96/12 = 8 days. 6 days treats the women as full men (16 workers).","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-104","question":"A and B start from the same point of a 600 m circular track at the same moment and run in opposite directions at 5 m/s and 7 m/s. If they keep running forever, at how many distinct points on the track do they meet?","options":["12","2","7","35"],"answer":0,"explanation":"They meet every 600/(5 + 7) = 50 s, and A advances 250 m between meetings. Meeting points are 250k mod 600, which take 600/gcd(250, 600) = 12 distinct values. Shortcut: for speeds in lowest ratio a : b, opposite runners meet at a + b points. 2 = 7 − 5 is the answer for the same direction.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-105","question":"A trader buys goods at 10% below the list price and sells them at 20% above the list price, but gives 1 article free with every 5 bought. What is his profit percentage?","options":["10%","11 1/9%","8%","33 1/3%"],"answer":1,"explanation":"Take list price 100. Cost per article = 90. For 6 articles handed over he receives 5 × 120 = 600, i.e. 100 per article. Profit = 10/90 = 11 1/9%. 10% takes profit on the list price; 33 1/3% ignores the free article.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-106","question":"The product of three consecutive positive integers is 8 times their sum. What is their sum?","options":["12","18","15","24"],"answer":2,"explanation":"Let them be n − 1, n, n + 1: product n(n² − 1), sum 3n. n(n² − 1) = 24n ⇒ n² = 25 ⇒ n = 5. The numbers are 4, 5, 6: product 120, sum 15, and 120 = 8 × 15. 24 is n² − 1, not the sum.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-advanced-quant-107","question":"How many zeros are there at the end of the number 1¹ × 2² × 3³ × 4⁴ × … × 25²⁵?","options":["50","6","60","100"],"answer":3,"explanation":"Count factors of 5 (2s are plentiful). 5⁵, 10¹⁰, 15¹⁵ and 20²⁰ give 5 + 10 + 15 + 20 = 50; 25²⁵ = 5⁵⁰ gives 50 more. Total 100. 6 is the count for 25!; 50 forgets that 25 carries two 5s.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-108","question":"A hall measures 15.17 m by 9.02 m. It is to be paved with identical square tiles of the largest possible size, without cutting any tile. How many tiles are needed?","options":["814","41","1517","902"],"answer":0,"explanation":"In cm the sides are 1517 and 902. HCF(1517, 902) = 41 (1517 = 37 × 41, 902 = 22 × 41), so each tile is 41 cm square and the count is 37 × 22 = 814. 41 is the tile side, not the number of tiles.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-advanced-quant-109","question":"At what time between 3 and 4 o’clock is the minute hand exactly 10 minute-spaces ahead of the hour hand?","options":["5 5/11 minutes past 3","27 3/11 minutes past 3","25 minutes past 3","27 minutes past 3"],"answer":1,"explanation":"At 3:00 the hour hand is 15 spaces ahead. The minute hand gains 11/12 space per minute and must gain 15 + 10 = 25 spaces: 25 × 12/11 = 300/11 = 27 3/11 minutes. 5 5/11 minutes is when it is 10 spaces behind (gain of only 5).","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-advanced-quant-110","question":"What is the sum of the digits of 10²⁵ − 25?","options":["225","216","219","207"],"answer":2,"explanation":"10²⁵ − 25 = 999…975, with 23 nines followed by 7 and 5 (25 digits in all). Digit sum = 23 × 9 + 7 + 5 = 219. 225 assumes 25 nines; 216 = 24 × 9 miscounts the nines.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-advanced-quant-111","question":"What is the remainder when 17^(19²¹) (17 raised to the power 19²¹) is divided by 100?","options":["53","17","73","89"],"answer":0,"explanation":"17 is coprime to 100 and 17²⁰ ≡ 1 (mod 100) (check: 17² = 289 ≡ 89, 17⁴ ≡ 21, 17⁵ ≡ 57, 17¹⁰ ≡ 49, 17²⁰ ≡ 1). So only 19²¹ mod 20 matters: 19 ≡ −1, and an odd power of −1 is −1, i.e. 19. Hence the answer is 17¹⁹ ≡ 17⁻¹ (mod 100). Since 17 × 53 = 901 ≡ 1, the remainder is 53. 17 comes from reducing the exponent to 1 instead of −1; 89 is 17², from reducing the exponent mod 4 carelessly.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-112","question":"For how many positive integers n ≤ 1000 is n² + n + 1 divisible by 91?","options":["22","44","11","40"],"answer":1,"explanation":"91 = 7 × 13. Mod 7, n² + n + 1 ≡ 0 has roots n ≡ 2, 4. Mod 13 it has roots n ≡ 3, 9. By the Chinese Remainder Theorem each of the 2 × 2 combinations gives one residue mod 91: n ≡ 9, 16, 74, 81. In 1…1000 there are 10 full blocks of 91 (up to 910) giving 40, and in 911…1000 (residues 1…90) all four residues occur again, so 44. 40 forgets the last partial block; 22 counts only two residues, as if a quadratic could have only two roots modulo a composite number.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-113","question":"For how many positive integers n is n² + 2024 a perfect square?","options":["8","2","4","16"],"answer":2,"explanation":"Let n² + 2024 = m², so (m − n)(m + n) = 2024 = 2³ × 11 × 23. The two factors differ by 2n, so they have the same parity, and since the product is even both must be even: write them as 2a and 2b with ab = 506 = 2 × 11 × 23. 506 has 8 divisors, giving 4 unordered pairs a < b (a = b is impossible), each with a positive n = b − a. So there are 4 values (n = 1, 35, 115, 252). 8 counts every factor pair of 2024, including the odd × even ones that give a fractional n.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-114","question":"For how many positive integers n does n! end in exactly 30 zeros?","options":["5","1","4","0"],"answer":3,"explanation":"The number of trailing zeros of n! is ⌊n/5⌋ + ⌊n/25⌋ + ⌊n/125⌋ + … For n = 120 to 124 this is 24 + 4 = 28. At n = 125 the count jumps by three (125 = 5³ adds three fives at once) to 25 + 5 + 1 = 31. So the values 29 and 30 are skipped altogether and no factorial ends in exactly 30 zeros. 5 is the usual answer (five consecutive n share each attainable count), but it assumes every count is attainable.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-115","question":"A function f satisfies f(x) + f(1/(1 − x)) = x for every real x other than 0 and 1. What is f(2)?","options":["7/4","3/4","1","5/4"],"answer":0,"explanation":"The map x → 1/(1 − x) cycles with period 3: 2 → −1 → 1/2 → 2. Put x = 2, −1, 1/2: f(2) + f(−1) = 2; f(−1) + f(1/2) = −1; f(1/2) + f(2) = 1/2. Add the first and third and subtract the second: 2f(2) = 2 + 1/2 − (−1) = 7/2, so f(2) = 7/4. 1 comes from wrongly assuming f(2) = f(−1) in the first equation.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-116","question":"x, y and z are positive real numbers with x + y + z = 12. What is the maximum value of x·y²·z³?","options":["4096","6912","5184","7776"],"answer":1,"explanation":"Split the sum into six parts whose product is proportional to the target: x, y/2, y/2, z/3, z/3, z/3 add up to 12, so by AM–GM their product is at most (12/6)⁶ = 64, with equality when all are 2, i.e. x = 2, y = 4, z = 6. Then x·y²·z³ = 64 × 2² × 3³ = 6912 (check: 2 × 16 × 216). 4096 is the value at x = y = z = 4, which is where the plain product xyz, not x·y²·z³, peaks.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-117","question":"What is the minimum value of f(x) = |x − 1| + |2x − 5| + |4x − 18| over all real x?","options":["9.5","8","7.5","7"],"answer":2,"explanation":"f is piecewise linear with corners at x = 1, 2.5 and 4.5. Its slope is −7 for x < 1, −5 on (1, 2.5), −1 on (2.5, 4.5) and +7 beyond 4.5, so it keeps falling until x = 4.5 and the minimum is f(4.5) = 3.5 + 4 + 0 = 7.5. The coefficients act as weights (1, 2, 4), so the minimum sits at the weighted median 4.5, not the middle corner: f(2.5) = 9.5 is the tempting wrong answer.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-118","question":"Two circles of radii 9 cm and 4 cm touch each other externally and both rest on a straight line. A third circle is drawn in the gap between them so that it touches both circles and the line. What is its radius?","options":["1.5 cm","2 cm","1.2 cm","1.44 cm"],"answer":3,"explanation":"For two circles of radii a and b resting on a line and touching each other, the points of contact with the line are 2√(ab) apart (right triangle with hypotenuse a + b and one leg a − b). Applying this to the three pairs: 2√(9r) + 2√(4r) = 2√(9 × 4), so 3√r + 2√r = 6, √r = 6/5 and r = 36/25 = 1.44 cm. 2 cm comes from guessing a harmonic-type mean of the radii; the relation is in the square roots: 1/√r = 1/√9 + 1/√4.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-119","question":"In triangle ABC, AB = 10 cm, AC = 17 cm and BC = 21 cm. A square is drawn inside the triangle with one side lying on BC and the other two vertices on AB and AC. What is the side of the square?","options":["168/29 cm","6 cm","84/13 cm","56/9 cm"],"answer":0,"explanation":"Heron: s = 24, area = √(24 × 3 × 14 × 7) = 84 cm², so the altitude from A to BC is 2 × 84/21 = 8 cm. The top side of the square cuts off a triangle similar to ABC with altitude 8 − x and base x, so x/21 = (8 − x)/8, giving 8x = 168 − 21x and x = 168/29 ≈ 5.79 cm. In general x = ah/(a + h). 6 cm is only a rounded guess; 84/13 divides the area by something perimeter-like, as one would for an inradius; the square needs the similar-triangle relation instead.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-120","question":"P is a point inside a circle of radius 13 cm, at a distance of 5 cm from the centre. How many chords of the circle pass through P and have a length that is a whole number of centimetres?","options":["3","4","2","5"],"answer":1,"explanation":"The shortest chord through P is the one perpendicular to the line joining P to the centre: 2√(13² − 5²) = 24 cm. The longest is the diameter, 26 cm. Every length strictly between occurs for exactly two chords (mirror images in the diameter through P), while the extremes occur once each. Integer lengths: 24 (one chord), 25 (two chords), 26 (one chord), so 4 chords. 3 counts the lengths 24, 25, 26 rather than the chords.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-121","question":"An escalator moves upward at a constant speed. Asha walks up it and reaches the top after taking 30 steps. Bala walks DOWN the same upward-moving escalator, stepping three times as fast as Asha, and reaches the bottom after taking 150 steps. How many steps are visible on the escalator when it is stationary?","options":["90","60","75","120"],"answer":2,"explanation":"Let the escalator move k steps in the time Asha takes one step. Going up, Asha's 30 steps are helped by 30k escalator steps: N = 30 + 30k. Bala takes 150 steps in the time Asha would take 50, during which the escalator carries him back 50k steps: N = 150 − 50k. So 30 + 30k = 150 − 50k, k = 1.5 and N = 75. 90 is the plain average of 30 and 150, which ignores that the two walkers spend different times on the escalator.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-122","question":"Pipes A and B can fill a tank in 20 minutes and 30 minutes respectively. An outlet pipe C, which can empty the full tank in 15 minutes, is fitted with a sensor: C is open whenever the tank is at least half full and closed otherwise. If A and B are opened together on the empty tank, in how many minutes will it be full?","options":["60 minutes","24 minutes","30 minutes","36 minutes"],"answer":3,"explanation":"Up to the half mark only A and B work: rate 1/20 + 1/30 = 1/12 per minute, so half the tank takes 6 minutes. Above the half mark C is open and the net rate is 1/12 − 1/15 = 1/60 per minute; this is still positive, so the level keeps rising and the second half takes 30 minutes. Total 36 minutes. 60 minutes assumes C is open from the start; 30 minutes forgets the first 6 minutes.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-123","question":"Vessel A holds 40 litres of milk and vessel B holds 40 litres of water. 10 litres are poured from A into B and stirred, then 10 litres are poured back from B into A and stirred. This whole two-step operation is carried out twice. How many litres of milk are in vessel A at the end?","options":["27.2 litres","28.8 litres","25.6 litres","26 litres"],"answer":0,"explanation":"Track the milk in A. Round 1: A keeps 30 L milk; B has 10 L milk in 50 L, so 10 L poured back carries 2 L milk: A has 32 L milk, B has 8 L. Round 2: 10 L from A carries 8 L milk, leaving 24 L; B now has 16 L milk in 50 L, so 10 L back carries 3.2 L: A has 27.2 L. Shortcut: each round multiplies the gap (milk in A − milk in B) by 3/5: 40 → 24 → 14.4, and A = (40 + 14.4)/2 = 27.2. 25.6 = 40 × 0.8² treats the return pour as pure water.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-124","question":"A sequence is defined by a₁ = 2, a₂ = 3 and aₙ₊₂ = aₙ₊₁/aₙ for n ≥ 1. What is a₂₀₂₆?","options":["3/2","1/2","1/3","2/3"],"answer":1,"explanation":"Compute a few terms: 2, 3, 3/2, 1/2, 1/3, 2/3, 2, 3, … The recurrence gives aₙ₊₃ = 1/aₙ, so the sequence repeats with period 6. 2026 = 6 × 337 + 4, so a₂₀₂₆ = a₄ = 1/2. 2/3 is a₆, the result of treating a remainder of 4 as 'two before the end of the cycle'; 3/2 is a₃ from an off-by-one in the remainder.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-125","question":"If log₁₂ 18 = a, what is log₂₄ 16 in terms of a?","options":["(8 − 4a)/(5 + a)","(4 − 2a)/(5 − a)","(8 − 4a)/(5 − a)","(8 + 4a)/(5 − a)"],"answer":2,"explanation":"Let t = log₂ 3. Then a = log₂ 18/log₂ 12 = (1 + 2t)/(2 + t), so 2a + at = 1 + 2t and t = (2a − 1)/(2 − a). Now log₂₄ 16 = 4/(3 + t) = 4(2 − a)/(3(2 − a) + 2a − 1) = (8 − 4a)/(5 − a). Check with a ≈ 1.163: about 0.872, and log₂₄ 16 = 4 ln 2/ln 24 ≈ 0.872. (4 − 2a)/(5 − a) is log₂₄ 4, from writing 16 as 2² instead of 2⁴.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-126","question":"How many integers x satisfy log₁⁄₃ (x² − 8x + 15) ≥ −1? (The base of the logarithm is 1/3.)","options":["5","3","0","2"],"answer":3,"explanation":"The base 1/3 is below 1, so the inequality reverses: 0 < x² − 8x + 15 ≤ (1/3)⁻¹ = 3. The right part gives x² − 8x + 12 ≤ 0, i.e. 2 ≤ x ≤ 6. The left part (the domain) needs (x − 3)(x − 5) > 0, i.e. x < 3 or x > 5. Together: 2 ≤ x < 3 or 5 < x ≤ 6, so only x = 2 and x = 6 (both give log₁⁄₃ 3 = −1). 5 forgets the domain (x = 3, 4, 5 make the argument zero or negative); 3 keeps x = 3 or x = 5, where the logarithm is not defined.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-127","question":"A polynomial p(x) leaves remainders 2, 5 and 12 when divided by (x − 1), (x − 2) and (x − 3) respectively. If r(x) is the remainder when p(x) is divided by (x − 1)(x − 2)(x − 3), what is r(0)?","options":["3","−1","2","1"],"answer":0,"explanation":"r(x) has degree at most 2 and must agree with p at x = 1, 2, 3: r(1) = 2, r(2) = 5, r(3) = 12. First differences are 3 and 7, second difference 4, so the leading coefficient is 2 and r(x) = 2x² − 3x + 3 (check: 2, 5, 12). Hence r(0) = 3. Equivalently, extend the difference table backwards: the first difference before 3 is −1, so r(0) = 2 − (−1) = 3. −1 is that backward difference itself, not the value; 1 comes from assuming a linear remainder through the first two points and ignoring the third.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-128","question":"What is the sum of all positive integers less than 1000 that are coprime to 1000?","options":["400000","200000","250000","199600"],"answer":1,"explanation":"The count of such integers is φ(1000) = 1000 × (1 − 1/2)(1 − 1/5) = 400. If k is coprime to 1000 then so is 1000 − k, and the two are different (k = 500 is not coprime), so the 400 numbers split into 200 pairs each summing to 1000. Sum = 200 × 1000 = 200000. 400000 multiplies 400 by 1000 without halving; 250000 uses 'half the numbers below 1000' instead of φ(1000).","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-129","question":"What is the integer part (greatest integer not exceeding) of (3 + √5)⁵?","options":["3936","3934","3935","3904"],"answer":2,"explanation":"Let α = 3 + √5 and β = 3 − √5; they are the roots of x² − 6x + 4 = 0, so Sₙ = αⁿ + βⁿ is an integer with Sₙ = 6Sₙ₋₁ − 4Sₙ₋₂. S₀ = 2, S₁ = 6, S₂ = 28, S₃ = 144, S₄ = 752, S₅ = 3936. Since 0 < β ≈ 0.764 < 1, β⁵ ≈ 0.26 lies strictly between 0 and 1, so α⁵ = 3936 − β⁵ ≈ 3935.74 and its integer part is 3935. 3936 is S₅ itself: the conjugate term must be subtracted, not ignored.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-130","question":"Towns A and B are 60 km apart. Cyclist X leaves A for B at 18 km/h and, at the same moment, cyclist Y leaves B for A at 12 km/h. A fly starts from X at that moment and flies at 30 km/h to Y, turns instantly, flies back to X, and keeps shuttling between them until they meet. What total distance does the fly cover while flying in the direction from A towards B?","options":["36 km","45 km","30 km","48 km"],"answer":3,"explanation":"The cyclists close at 30 km/h, so they meet after 2 hours, 36 km from A; the fly covers 30 × 2 = 60 km in all. Let F be the distance it flies towards B and R the distance it flies back towards A. Then F + R = 60, and since it starts at A and ends at the meeting point, F − R = 36. So F = 48 km (and R = 12 km). 36 km is the fly's net displacement, 30 km assumes it spends half its time in each direction; neither is the forward distance.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-131","question":"Ten distinct positive integers have an average of 20. What is the greatest possible value of the sixth smallest of them?","options":["35","37","34","36"],"answer":0,"explanation":"The sum is 200. To push the sixth smallest (call it x) as high as possible, make the five numbers below it as small as possible, 1 + 2 + 3 + 4 + 5 = 15, and the four numbers above it as small as possible, x + 1, x + 2, x + 3, x + 4. Then 15 + 5x + 10 ≤ 200, so x ≤ 35, and x = 35 works exactly (1–5 and 35–39 sum to 200). 37 comes from forgetting that the four larger numbers must be distinct and exceed x, i.e. using 15 + 5x ≤ 200.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-132","question":"For how many positive integers n is ⌊n/7⌋ = ⌊n/9⌋? (⌊x⌋ is the greatest integer not exceeding x.)","options":["12","15","18","6"],"answer":1,"explanation":"Let the common value be k. Then 7k ≤ n < 7k + 7 and 9k ≤ n < 9k + 9, so n runs from 9k to 7k + 6, which is 7 − 2k values when that is positive. k = 0: n = 1…6 (6 values, since n must be positive); k = 1: n = 9…13 (5); k = 2: n = 18, 19, 20 (3); k = 3: n = 27 (1); k ≥ 4: none. Total 6 + 5 + 3 + 1 = 15. 6 stops at k = 0; 18 wrongly counts n = 0; the overlap must be measured from 9k up to 7k + 6.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-133","question":"For how many integers n with 1 ≤ n ≤ 100 is 2ⁿ − n divisible by 5?","options":["25","16","20","24"],"answer":2,"explanation":"2ⁿ mod 5 repeats with period 4 (2, 4, 3, 1) and n mod 5 with period 5, so the pair repeats with period 20. For each residue of n mod 4 the required residue of n mod 5 is fixed and never 0, and CRT gives exactly one n in each block of 20: n ≡ 1 (mod 4) and 2 (mod 5) → 17; n ≡ 2, 4 → 14; n ≡ 3, 3 → 3; n ≡ 0, 1 → 16. So 4 values per block of 20 (3, 14, 16, 17) and 4 × 5 = 20 values up to 100. 25 assumes 2ⁿ mod 5 behaves like a random residue hit 'one time in four'; 16 loses a block.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-134","question":"How many points with integer coordinates lie strictly inside the triangle with vertices (0, 0), (21, 0) and (0, 15)?","options":["140","136","157","139"],"answer":3,"explanation":"Use Pick's theorem: Area = I + B/2 − 1. The area is 21 × 15/2 = 157.5. Boundary points: 21 on the x-axis side plus 15 on the y-axis side plus gcd(21, 15) = 3 on the hypotenuse, B = 39. So I = 157.5 − 19.5 + 1 = 139. Check another way: the 20 × 14 = 280 interior points of the rectangle, minus the 2 lattice points on the diagonal strictly inside, halved: (280 − 2)/2 = 139. 140 forgets the two points on the hypotenuse; 157 is the area.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-135","question":"A solid right circular cone has base radius 6 cm and height 8 cm. The largest possible sphere is placed inside it, touching the base and the slant surface. A second, smaller sphere is then placed above the first so that it touches the first sphere and the slant surface all round. What is the radius of the smaller sphere?","options":["0.75 cm","1 cm","1.5 cm","0.6 cm"],"answer":0,"explanation":"Take the axial cross-section: an isosceles triangle with base 12, height 8 and slant sides 10. The large sphere is its incircle: r = area/semi-perimeter = 48/16 = 3 cm. The plane tangent to the top of this sphere cuts off a smaller cone of height 8 − 2 × 3 = 2 cm, similar to the original with ratio 2/8 = 1/4, and the small sphere is the insphere of that cone: 3 × 1/4 = 0.75 cm. 1.5 cm simply halves the radius; 0.6 cm applies sin of the semi-vertical angle (6/10) once more instead of using the similar cone of height 2 cm.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-136","question":"A milkman buys pure milk at ₹40 per litre, adds water (which costs nothing), and sells the mixture at ₹40 per 'litre' — but his litre measure actually holds only 900 ml. His overall gain works out to 38 8/9 %. In what ratio does he mix water and milk?","options":["1 : 5","1 : 4","1 : 3","2 : 7"],"answer":1,"explanation":"Let milk be a fraction m of the mixture. Each sale brings ₹40 for 900 ml of mixture, whose cost is 40 × 0.9 × m. Gain 38 8/9 % means selling price/cost = 25/18, so 1/(0.9m) = 25/18, 0.9m = 18/25 and m = 4/5. Water : milk = 1 : 4. Check: 900 ml of mixture holds 720 ml milk costing ₹28.80, sold for ₹40, gain 11.2/28.8 = 38 8/9 %. 1 : 3 comes from adding the two cheats (10% short measure + 25% water) instead of multiplying them.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-137","question":"The positive integers are written one after another without spaces: 123456789101112131415… What is the 2026th digit of this string?","options":["1","2","7","6"],"answer":2,"explanation":"One-digit numbers use 9 digits and two-digit numbers 90 × 2 = 180, so 189 digits bring us to the end of 99. We need 2026 − 189 = 1837 more digits from three-digit numbers. 1837 = 3 × 612 + 1, so 612 complete numbers (100 to 711) are used and the next digit is the first digit of 712, which is 7. 1 is the last digit of 711 (an off-by-one: 1836 digits end exactly there); 2 is the last digit of 712.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-138","question":"For how many integer values of k does the equation |x² − 6x + 5| = k have exactly four distinct real solutions?","options":["4","5","2","3"],"answer":3,"explanation":"The parabola y = x² − 6x + 5 has zeros at 1 and 5 and vertex (3, −4). Taking the absolute value folds the part between the zeros up into a hump of height 4. A horizontal line y = k meets the graph in 4 points only when it passes through the hump below its top: 0 < k < 4. (k = 0 gives 2 solutions, k = 4 gives 3, k > 4 gives 2.) So k = 1, 2, 3: three values. 4 wrongly includes k = 4, where the line only touches the top of the hump; 5 includes k = 0 as well.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-139","question":"An army convoy 3 km long moves along a straight road at a constant speed. A messenger on a motorcycle starts from the rear of the convoy, rides to the front, immediately turns back and returns to the rear, all at a constant speed. During this time the convoy moves forward 4 km. What distance does the messenger cover?","options":["8 km","10 km","6 km","7 km"],"answer":0,"explanation":"Measure speed in units of the convoy's speed and let the messenger's speed be v. Relative to the convoy he gains at v − 1 going forward and at v + 1 coming back, so the time is 3/(v − 1) + 3/(v + 1), and in that time the convoy covers 4 km: 6v/(v² − 1) = 4, i.e. 2v² − 3v − 2 = 0, v = 2. He travels twice as far as the convoy: 8 km (6 km forward, 2 km back). 10 km adds the convoy's 4 km to a 6 km round trip of the convoy's length; 6 km ignores the convoy's motion.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-advanced-quant-140","question":"An arithmetic progression consists of positive integers, has a positive integer common difference and at least 3 terms, and all its terms add up to 100. How many such progressions are there?","options":["18","20","21","12"],"answer":1,"explanation":"With first term a, difference d and n terms: n(2a + (n − 1)d) = 200, so n is a divisor of 200 with n ≥ 3, and the minimum possible sum n(n + 1)/2 ≤ 100 forces n ≤ 13: n = 4, 5, 8 or 10. n = 4: 2a + 3d = 50, d even, d = 2, 4, …, 16 → 8. n = 5: a + 2d = 20, d = 1…9 → 9. n = 8: 2a + 7d = 25, d odd, d = 1, 3 → 2. n = 10: 2a + 9d = 20, d = 2 → 1. Total 8 + 9 + 2 + 1 = 20. 18 drops the n = 8 case, where the average term 12.5 is not an integer but the progression still works (for example 9, 10, …, 16); 21 lets a constant progression (d = 0) slip in.","difficulty":"very-hard","source":"Product company OA · CAT level"},
];

